/** Rows of `ch` in a GOOFY_* font (lowercase -> uppercase, unknown -> '?'). */
export function goofyGlyph(font, ch) {
  return font.g[ch] || font.g[String(ch).toUpperCase()] || font.g['?'];
}

/** Width / height in px of `str` at an integer scale. */
export function goofyMeasure(font, str, scale = 1) {
  let w = 0;
  for (const ch of String(str)) w += (goofyGlyph(font, ch)[0].length + font.sp) * scale;
  return { w: Math.max(0, w - font.sp * scale), h: font.h * scale };
}

/** The text as one bitmap: { w, h, rows } ('#'/'.' strings), h covers every row drawn. */
export function goofyBitmap(font, str) {
  const gs = [...String(str)].map((ch) => goofyGlyph(font, ch));
  const h = Math.max(font.h, ...gs.map((g) => g.length));
  const w = gs.reduce((s, g) => s + g[0].length + font.sp, -font.sp);
  const rows = Array.from({ length: h }, () => []);
  for (const g of gs) {
    for (let y = 0; y < h; y++) rows[y].push(g[y] || '.'.repeat(g[0].length));
    if (font.sp) for (let y = 0; y < h; y++) rows[y].push('.'.repeat(font.sp));
  }
  return { w: Math.max(0, w), h, rows: rows.map((r) => r.join('').slice(0, Math.max(0, w))) };
}
